WITH budget_event_joined AS (
    SELECT e.type, b.spent, b.amount FROM budget b
    INNER JOIN event e ON b.link_to_event = e.event_id
    WHERE b.spent != 0 AND b.amount != 0
),
type_ratios AS (
    SELECT type, SUM(spent) / SUM(amount) AS total_spend_ratio FROM budget_event_joined GROUP BY type
),
overall_mean AS (
    SELECT AVG(total_spend_ratio) AS mean_of_ratios FROM type_ratios
)
SELECT tr.type, tr.total_spend_ratio, tr.total_spend_ratio - om.mean_of_ratios AS distance_from_mean
FROM type_ratios tr CROSS JOIN overall_mean om ORDER BY tr.type;

